CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar not null default 'student', "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "avatar" varchar, "headline" varchar, "bio" text, "points" integer not null default '0', "level" integer not null default '1');
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE "courses" ("id" integer primary key autoincrement not null, "title" varchar not null, "description" text, "thumbnail" varchar, "created_at" datetime, "updated_at" datetime, "price" numeric not null default '0', "is_published" tinyint(1) not null default '0', "user_id" integer);
CREATE TABLE "modules" ("id" integer primary key autoincrement not null, "course_id" integer not null, "title" varchar not null, "order" integer not null default '0', "description" text, "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE "sections" ("id" integer primary key autoincrement not null, "course_id" integer not null, "title" varchar not null, "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE "lessons" ("id" integer primary key autoincrement not null, "module_id" integer not null, "title" varchar not null, "description" varchar, "video_url" varchar, "duration" integer, "is_preview" tinyint(1) not null default '0', "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("module_id") references "modules"("id") on delete cascade);
CREATE TABLE "events" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "description" text, "thumbnail" varchar, "event_type" varchar not null, "delivery_type" varchar not null, "meeting_url" varchar, "location" text, "city" varchar, "recording_url" varchar, "start_time" datetime not null, "end_time" datetime not null, "timezone" varchar not null default 'WIB', "instructor_id" integer, "capacity" integer, "is_paid" tinyint(1) not null default '0', "price" numeric, "status" varchar not null default 'draft', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("instructor_id") references "users"("id") on delete set null);
CREATE UNIQUE INDEX "events_slug_unique" on "events" ("slug");
CREATE TABLE "transactions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer not null, "invoice_number" varchar not null, "amount" numeric not null, "status" varchar check ("status" in ('pending', 'paid', 'failed', 'cancelled')) not null default 'pending', "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE UNIQUE INDEX "transactions_invoice_number_unique" on "transactions" ("invoice_number");
CREATE TABLE "enrollments" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer not null, "status" varchar check ("status" in ('active', 'completed')) not null default 'active', "progress" integer not null default '0', "enrolled_at" datetime, "created_at" datetime, "updated_at" datetime, "completed_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE "discussions" ("id" integer primary key autoincrement not null, "course_id" integer not null, "lesson_id" integer not null, "user_id" integer not null, "content" text not null, "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade, foreign key("lesson_id") references "lessons"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "discussion_replies" ("id" integer primary key autoincrement not null, "discussion_id" integer not null, "user_id" integer not null, "content" text not null, "created_at" datetime, "updated_at" datetime, foreign key("discussion_id") references "discussions"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE INDEX "notifications_notifiable_type_notifiable_id_index" on "notifications" ("notifiable_type", "notifiable_id");
CREATE TABLE "lesson_completions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "lesson_id" integer not null, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("lesson_id") references "lessons"("id") on delete cascade);
CREATE UNIQUE INDEX "lesson_completions_user_id_lesson_id_unique" on "lesson_completions" ("user_id", "lesson_id");
CREATE TABLE "bookmarks" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE UNIQUE INDEX "bookmarks_user_id_course_id_unique" on "bookmarks" ("user_id", "course_id");
CREATE TABLE "page_views" ("id" integer primary key autoincrement not null, "user_id" integer, "url" varchar not null, "route_name" varchar, "ip_address" varchar, "user_agent" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
